#!/usr/bin/env python3
import os
import subprocess
import sys

CERT_PATH = "/app/ssl/server.crt"


def openssl(*args):
    return subprocess.check_output(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", *args],
        stderr=subprocess.STDOUT,
        text=True,
    ).strip()


def main():
    if not os.path.isfile(CERT_PATH):
        print(f"Certificate not found: {CERT_PATH}")
        return 1

    try:
        subject = openssl("-subject")
        end_date = openssl("-enddate").split("=", 1)[1]
        der = subprocess.check_output(
            ["openssl", "x509", "-in", CERT_PATH, "-outform", "DER"],
            stderr=subprocess.STDOUT,
        )
        if not der:
            raise ValueError("Certificate could not be parsed")
    except (subprocess.CalledProcessError, IndexError, ValueError) as exc:
        print(f"Certificate verification failed: {exc}")
        return 1

    common_name = ""
    for part in subject.replace("subject=", "").split(","):
        part = part.strip()
        if part.startswith("CN"):
            common_name = part.split("=", 1)[1].strip()
            break

    from datetime import datetime

    expiry = datetime.strptime(end_date, "%b %d %H:%M:%S %Y %Z")

    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {expiry.strftime('%Y-%m-%d')}")

    if not common_name or expiry < datetime.now():
        print("Certificate verification failed")
        return 1

    print("Certificate verification successful")
    return 0


if __name__ == "__main__":
    sys.exit(main())
